window.docContents[245].resolve({"/Citations/#A-Textbook--Citations":{"contents":"Cite works using citet, citep, or citehere.\nThey take a name of a citable reference value as a parameter.\nReferences should be defined as values, typically in one module that is imported (similar to the role of a .bib file in LaTeX).\n\nTextual citations, as with , look like this.\nParenthetical  looks like this.\nUse citehere to literally include the cite rather than making a margin note, e.g. .\nLiterally-included cites are mostly useful when performing citation inside a margin note.\n\n","context":"A Textbook","header":"5. Citations","id":"/Citations/#A-Textbook--Citations"},"/The-Natural-Numbers/#A-Textbook--The-Natural-Numbers":{"contents":"namespace MyNats\n\n\ninductive Nat where\n  | zero\n  | succ : Nat → Nat\n\n\ndef Nat.ofNat : _root_.Nat → Nat\n  | 0 => .zero\n  | n + 1 => .succ (.ofNat n)\n\n\ninstance : OfNat Nat n where\n  ofNat := .ofNat n\n\n\n@[match_pattern]\ndef Nat.add (n k : Nat) : Nat :=\n  match k with\n  | .zero => n\n  | .succ k' => .succ (n.add k')\n\n\ninstance : Add Nat where\n  add := Nat.add\n\n\ndef Nat.toNat : MyNats.Nat → _root_.Nat\n  | 0 => 0\n  | n + 1 => toNat n + 1\n\n\n#eval (4 : MyNats.Nat) + 2\n\n\nMyNats.Nat.succ\n  (MyNats.Nat.succ (MyNats.Nat.succ (MyNats.Nat.succ (MyNats.Nat.succ (MyNats.Nat.succ (MyNats.Nat.zero))))))\n\n\ninstance : Repr Nat where\n  reprPrec n _prec := repr n.toNat\n\ninstance : ReprAtom Nat where\n\n\n#eval (4 : MyNats.Nat) + 2\n\n\n6\n\n\nend MyNats\n\n\n","context":"A Textbook","header":"3. The Natural Numbers","id":"/The-Natural-Numbers/#A-Textbook--The-Natural-Numbers"},"/__________________/#A-Textbook--__________________":{"contents":"Verso では backtick 記法で\n\n$`y=f(x)\n\n\nと書くと y=f(x) となる\n\n","context":"A Textbook","header":"2. 数式のテスト","id":"/__________________/#A-Textbook--__________________"}});